#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Catamailer.Domain;

namespace Catamailer.Application
{
    /// <summary>
    /// Moteur d'exécution de l'Étape 2 : évaluation de l'arbre booléen des conditions.
    /// </summary>
    public class ExecutionEngine
    {
        /// <summary>
        /// Évalue un nœud de règle composite par rapport aux métadonnées textuelles d'un e-mail.
        /// </summary>
        /// <param name="subject">Le sujet de l'e-mail.</param>
        /// <param name="sender">L'adresse de l'expéditeur.</param>
        /// <param name="node">Le nœud composite à évaluer.</param>
        /// <returns>True si l'arbre est validé, False sinon.</returns>
        public bool Evaluate(string subject, string sender, RuleNode node)
        {
            return Evaluate(subject, sender, Enumerable.Empty<string>(), node);
        }

        /// <summary>
        /// Évalue un nœud de règle composite par rapport aux métadonnées complètes (incluant les catégories) d'un e-mail.
        /// </summary>
        /// <param name="subject">Le sujet de l'e-mail.</param>
        /// <param name="sender">L'adresse de l'expéditeur.</param>
        /// <param name="categories">Les catégories déjà appliquées à l'e-mail.</param>
        /// <param name="node">Le nœud composite à évaluer.</param>
        /// <returns>True si l'arbre est validé, False sinon.</returns>
        public bool Evaluate(string subject, string sender, IEnumerable<string>? categories, RuleNode node)
        {
            if (node == null || (!node.Criteria.Any() && !node.ChildNodes.Any()))
            {
                return false;
            }

            var categoryList = categories?.ToList() ?? new List<string>();

            if (node.Operator == LogicalOperator.And)
            {
                foreach (var criterion in node.Criteria)
                {
                    if (!EvaluateCriterion(subject, sender, categoryList, criterion))
                    {
                        return false;
                    }
                }

                foreach (var childNode in node.ChildNodes)
                {
                    if (!Evaluate(subject, sender, categoryList, childNode))
                    {
                        return false;
                    }
                }

                return true;
            }
            else
            {
                foreach (var criterion in node.Criteria)
                {
                    if (EvaluateCriterion(subject, sender, categoryList, criterion))
                    {
                        return true;
                    }
                }

                foreach (var childNode in node.ChildNodes)
                {
                    if (Evaluate(subject, sender, categoryList, childNode))
                    {
                        return true;
                    }
                }

                return false;
            }
        }

        /// <summary>
        /// Évalue un critère unitaire par rapport aux métadonnées de l'e-mail.
        /// </summary>
        private bool EvaluateCriterion(string subject, string sender, IReadOnlyList<string> categories, RuleCriterion criterion)
        {
            if (criterion.Field == MailField.Category)
            {
                if (string.IsNullOrWhiteSpace(criterion.Value) || categories.Count == 0)
                {
                    return false;
                }

                string target = criterion.Value.Trim();

                return criterion.Operator switch
                {
                    MatchOperator.ExactNode => categories.Any(c => string.Equals(c.Trim(), target, StringComparison.OrdinalIgnoreCase)),
                    MatchOperator.NodeAndChildren => categories.Any(c =>
                        string.Equals(c.Trim(), target, StringComparison.OrdinalIgnoreCase) ||
                        c.Trim().StartsWith(target + "-", StringComparison.OrdinalIgnoreCase)),
                    _ => false
                };
            }

            string valueToTest = criterion.Field switch
            {
                MailField.Subject => subject ?? string.Empty,
                MailField.Sender => sender ?? string.Empty,
                _ => string.Empty
            };

            return criterion.Operator switch
            {
                MatchOperator.Equals => string.Equals(valueToTest, criterion.Value, StringComparison.OrdinalIgnoreCase),
                MatchOperator.Contains => valueToTest.Contains(criterion.Value, StringComparison.OrdinalIgnoreCase),
                MatchOperator.RegexMatch => EvaluateRegex(valueToTest, criterion.Value),
                _ => false
            };
        }

        private static bool EvaluateRegex(string input, string pattern)
        {
            if (string.IsNullOrEmpty(pattern))
            {
                return false;
            }

            try
            {
                return Regex.IsMatch(input, pattern, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            }
            catch (ArgumentException)
            {
                return false;
            }
        }
    }
